use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
fn execute_command (state : & mut ReplState , input : & str) -> Result < bool > { let parts : Vec < & str > = input . split_whitespace () . collect () ; match parts . get (0) { Some (& "quit") | Some (& "exit") => { return Ok (false) ; } Some (& "set") => { if parts . len () < 2 { println ! ("Usage: set <var>=<value>") ; return Ok (true) ; } let assignment = parts [1 ..] . join (" ") ; if let Some ((key , value)) = assignment . split_once ('=') { state . variables . insert (key . trim () . to_string () , value . trim () . to_string ()) ; println ! ("✅ Set {} = {}" , key . trim () , value . trim ()) ; } else { println ! ("❌ Invalid format. Use: set var=value") ; } } Some (& "get") => { if let Some (var) = parts . get (1) { if let Some (value) = state . variables . get (* var) { println ! ("{} = {}" , var , value) ; } else { println ! ("❌ Variable '{}' not found" , var) ; } } else { println ! ("📋 Variables:") ; for (key , value) in & state . variables { println ! ("  {} = {}" , key , value) ; } } } Some (& "save") => { state . save_to_file () ? ; } Some (& "load") => { if let Some (source) = parts . get (1) { if source . starts_with ("http") { * state = ReplState :: load_from_url (source) ? ; } else { * state = ReplState :: load_from_file_path (source) ? ; } } else { * state = ReplState :: load_from_file () ? ; } } Some (& "export") => { if let Some (export_type) = parts . get (1) { let blob = RdfUrlBlob :: from_system_state (& state . system) ? ; match blob . export (export_type) { Ok (content) => println ! ("{}" , content) , Err (e) => println ! ("❌ Export failed: {}" , e) , } } else { println ! ("Usage: export <macros|code|docs|workspace|rdf|url>") ; } } Some (& "info") => { let blob = RdfUrlBlob :: from_system_state (& state . system) ? ; blob . print_info () ; println ! ("📊 REPL Stats:") ; println ! ("  Variables: {}" , state . variables . len ()) ; println ! ("  History: {} commands" , state . history . len ()) ; } Some (& "history") => { println ! ("📜 Command History:") ; for (i , cmd) in state . history . iter () . enumerate () { println ! ("  {}: {}" , i + 1 , cmd) ; } } Some (& "clear") => { state . variables . clear () ; state . history . clear () ; println ! ("🧹 Cleared variables and history") ; } Some (& "macro") => { if parts . len () < 3 { println ! ("Usage: macro <name> <code>") ; return Ok (true) ; } let name = parts [1] . to_string () ; let code = parts [2 ..] . join (" ") ; let decl = MacroDeclaration { name : name . clone () , source_path : format ! ("repl:{}" , name) , declaration_type : "macro" . to_string () , content : code . clone () , wrapper : Some (code) , } ; state . system . macros . insert (name . clone () , decl) ; println ! ("✅ Added macro: {}" , name) ; } Some (& "call") => { if let Some (macro_name) = parts . get (1) { if let Some (decl) = state . system . macros . get (* macro_name) { println ! ("🎭 Calling macro: {}" , macro_name) ; println ! ("📄 Content:") ; println ! ("{}" , decl . content) ; if let Some (wrapper) = & decl . wrapper { println ! ("🔧 Wrapper:") ; println ! ("{}" , wrapper) ; } } else { println ! ("❌ Macro '{}' not found" , macro_name) ; } } else { println ! ("Usage: call <macro_name>") ; } } Some (& "help") => { println ! ("📖 Available Commands:") ; println ! ("  set <var>=<value>  - Set a variable") ; println ! ("  get [var]          - Get variable or list all") ; println ! ("  macro <name> <code> - Define a macro") ; println ! ("  call <macro_name>  - Execute a loaded macro") ; println ! ("  save               - Save state to file") ; println ! ("  load [url|file]    - Load state from file or GitHub URL") ; println ! ("  export <type>      - Export (macros|code|docs|workspace|rdf|url)") ; println ! ("  info               - Show state information") ; println ! ("  history            - Show command history") ; println ! ("  clear              - Clear variables and history") ; println ! ("  help               - Show this help") ; println ! ("  quit/exit          - Exit REPL") ; } _ => { println ! ("❓ Unknown command: {}. Type 'help' for available commands." , input) ; } } Ok (true) }
}